overview:
{
  "overview": "The Marathon County Environmental Resources Committee met on September 29, 2026, to conduct public hearings on nine rezoning petitions, approve land acquisition and a boat donation for parks, review three independent town ordinances, and begin initial discussions on developing a data center ordinance under an existing 12-month moratorium. Eight of nine rezoning petitions were approved unanimously; one was postponed pending town board action. The data center ordinance discussion highlighted committee concerns about water use, electricity demand, noise, and the need for independent expert education before drafting standards.",
  "committee": "Marathon County Environmental Resources Committee",
  "presiding": "Supervisor Mike Ritter, Chair",
  "agenda": [
    {"time": "0:00", "item": "Call to Order and Pledge of Allegiance"},
    {"time": "1:10", "item": "Public Comment"},
    {"time": "1:20", "item": "Approval of September 1, 2026 Committee Minutes"},
    {"time": "2:05", "item": "5A1: Rezoning - White Knight Acres LLC, General Agriculture to Rural Residential, Town of Wayne"},
    {"time": "7:30", "item": "5A2: Rezoning - Elizabeth Kurt and Doug and Barb Kurt, General Agriculture/Rural Residential to General Agriculture/Rural Residential, Town of Huitt"},
    {"time": "13:00", "item": "5A3: Rezoning - Donna Klein Tippy, General Agriculture to Rural Residential, Town of Reed"},
    {"time": "18:30", "item": "5A4: Rezoning - Dwayne Johnson, Low Density Residential and Farmland Preservation to Rural Estate, Town of Hull"},
    {"time": "25:00", "item": "5A5: Rezoning - Thomas and Pamela Balls and Devon and Louisa Lammansky, General Agriculture to Low Density Residential, Town of Rib Falls"},
    {"time": "30:00", "item": "5A6: Rezoning - Austin Leel, General Agriculture to Rural Estate, Town of Holton"},
    {"time": "35:00", "item": "5A7: Rezoning - Marvin Martin, Farmland Preservation to Light Industrial, Town of Hull"},
    {"time": "39:30", "item": "5A8: Rezoning - Jordan Reynolds, Farmland Preservation to Rural Estate, Town of Hull"},
    {"time": "44:30", "item": "5A9: Rezoning - Spencer Joint Revocable Trust, Farmland Preservation to General Agriculture, Town of McMillan - POSTPONED"},
    {"time": "49:00", "item": "5C1: Possible Recommendation to County Board - Acquisition of Land Adjacent to Cherokee Park"},
    {"time": "1:02:00", "item": "5C2: Possible Recommendation to County Board - Donation of Pontoon Boat to Parks Department"},
